import{_ as n,o as a,c as t,ae as i}from"./chunks/framework.B2FZg54p.js";const o="/heidrun/experiments/web-doc-by-ai/documentation_images/pin_a_pane/pin_button.svg",p="/heidrun/experiments/web-doc-by-ai/documentation_images/pin_a_pane/pinned_column.svg",m=JSON.parse('{"title":"Pin and unpin a pane","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/pin_a_pane.md","filePath":"documentation/pin_a_pane.md"}'),r={name:"documentation/pin_a_pane.md"};function s(h,e,l,d,c,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="pin-and-unpin-a-pane" tabindex="-1">Pin and unpin a pane <a class="header-anchor" href="#pin-and-unpin-a-pane" aria-label="Permalink to &quot;Pin and unpin a pane&quot;">​</a></h1><p>Keep a terminal visible while you switch tabs, then return the terminal to its own tab.</p><h2 id="find-the-pin-button" tabindex="-1">Find the pin button <a class="header-anchor" href="#find-the-pin-button" aria-label="Permalink to &quot;Find the pin button&quot;">​</a></h2><p>A pane is one terminal inside a tab. Its pin button is in the pane header, beside the buttons for splitting and closing the pane.</p><p><img src="'+o+'" alt="The pane header with the pin button outlined"></p><p>The column of pinned panes appears at the right edge of the viewport, beside the panes of the selected tab. It is separate from the right sidebar.</p><h2 id="pin-a-pane" tabindex="-1">Pin a pane <a class="header-anchor" href="#pin-a-pane" aria-label="Permalink to &quot;Pin a pane&quot;">​</a></h2><ol><li>Click the pin button in the pane header. The pane moves into the column of pinned panes.</li><li>Select another tab. The pinned pane stays visible beside that tab’s panes, including when you select the tab that owns the pane.</li></ol><p>Pinning changes where the pane is shown; the pane still belongs to its original tab.</p><p><img src="'+p+'" alt="The pinned pane in the column at the right edge of the viewport, with Unpin the pane outlined"></p><h2 id="unpin-a-pane" tabindex="-1">Unpin a pane <a class="header-anchor" href="#unpin-a-pane" aria-label="Permalink to &quot;Unpin a pane&quot;">​</a></h2><ol><li>Click <strong>Unpin the pane</strong> in the pinned pane’s header.</li><li>If another tab is selected, select the pane’s own tab to see the pane there again.</li></ol><p>The pane returns to its own tab. When another tab is selected, the pane disappears from the column of pinned panes.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><section class="documentation-troubleshooting-topic" aria-label="Another pane cannot be pinned"><h3 id="another-pane-cannot-be-pinned" tabindex="-1">Another pane cannot be pinned <a class="header-anchor" href="#another-pane-cannot-be-pinned" aria-label="Permalink to &quot;Another pane cannot be pinned&quot;">​</a></h3><p><strong>Cause</strong>: Heidrun allows at most four pinned panes.</p><p><strong>Solution</strong>:</p><ol><li>Click <strong>Unpin the pane</strong> in a pinned pane’s header.</li><li>Try pinning the other pane again.</li></ol><p><strong>Check</strong>: The other pane appears in the column of pinned panes.</p></section><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/tabs.html">Create, select and rename tabs</a>: to switch to a tab or create one.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/pane_focus_history.html">Return to a previously focused pane</a>: to return to a pane you focused earlier.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/shortcuts.html">Keyboard shortcuts</a>: to look up keyboard commands.</li></ul>',17)])])}const _=n(r,[["render",s]]);export{m as __pageData,_ as default};
